module TopModule (
    input  logic clk,
    input  logic load,
    input  logic [255:0] data,
    output logic [255:0] q
);

    logic [255:0] q_next;

    // Combinational next-state logic: one step of Conway's Game of Life
    always_comb
    begin
        for (int i = 0; i < 256; i++)
        begin
            // Map linear index to 2D coordinates (row, col)
            int r = i >> 4;   // row 0..15
            int c = i & 15;   // col 0..15

            // Toroidal (wrap-around) neighbour coordinates
            int r_up    = (r - 1 + 16) % 16;
            int r_down  = (r + 1) % 16;
            int c_left  = (c - 1 + 16) % 16;
            int c_right = (c + 1) % 16;

            // Linear indices of the 8 neighbours
            int n1 = (r_up << 4) | c_left;    // NW
            int n2 = (r_up << 4) | c;         // N
            int n3 = (r_up << 4) | c_right;  // NE
            int n4 = (r << 4) | c_left;       // W
            int n5 = (r << 4) | c_right;      // E
            int n6 = (r_down << 4) | c_left;  // SW
            int n7 = (r_down << 4) | c;       // S
            int n8 = (r_down << 4) | c_right; // SE

            // Count live neighbours (each q bit is 0 or 1)
            int sum = q[n1] + q[n2] + q[n3] + q[n4] +
                      q[n5] + q[n6] + q[n7] + q[n8];

            // Apply Game of Life rules
            if (sum <= 1)
                q_next[i] = 1'b0;
            else if (sum == 2)
                q_next[i] = q[i];      // stay unchanged
            else if (sum == 3)
                q_next[i] = 1'b1;      // become alive
            else // sum >= 4
                q_next[i] = 1'b0;      // become dead
        end
    end

    // Sequential logic: synchronous load, positive-edge-triggered
    always_ff @(posedge clk)
    begin
        if (load)
            q <= data;
        else
            q <= q_next;
    end

endmodule

