module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic [7:0] in,
    output logic done
);

// State encoding
typedef enum logic [1:0] {
    IDLE   = 2'b00,
    GOT1   = 2'b01,
    GOT2   = 2'b10,
    GOT3   = 2'b11
} state_t;

state_t state, next_state;

// State register: positive-edge triggered, synchronous active-high reset
always_ff @(posedge clk or posedge reset) begin
    if (reset)
        state <= IDLE;
    else
        state <= next_state;
end

// Next-state combinational logic
always_comb begin
    case (state)
        IDLE: begin
            if (in[3])
                next_state = GOT1;
            else
                next_state = IDLE;
        end
        GOT1: next_state = GOT2;
        GOT2: next_state = GOT3;
        GOT3: next_state = IDLE;
        default: next_state = IDLE;
    endcase
end

// Output: done is asserted high in the cycle immediately after the third byte
// of a message was successfully received (i.e., while state is GOT3).
assign done = (state == GOT3);

endmodule

