module TopModule (
    input  logic        clk,
    input  logic        load,
    input  logic [511:0] data,
    output logic [511:0] q
);

    // Current state of the 512‑cell cellular automaton
    logic [511:0] q_reg;

    // Next state computed by Rule 110
    logic [511:0] next_q;

    // Combinational logic: compute next state for all cells
    always_comb begin
        integer i;
        for (i = 0; i < 512; i = i + 1) begin
            logic left, center, right;

            // Left neighbour: cell 0 has left=0, else previous cell
            if (i == 0)
                left = 1'b0;
            else
                left = q_reg[i-1];

            // Center is the cell's current state
            center = q_reg[i];

            // Right neighbour: cell 511 has right=0, else next cell
            if (i == 511)
                right = 1'b0;
            else
                right = q_reg[i+1];

            // Rule 110 next‑state truth table
            // (Left, Center, Right) → Next
            // 111 → 0, 110 → 1, 101 → 1, 100 → 0,
            // 011 → 1, 010 → 1, 001 → 1, 000 → 0
            next_q[i] = ((~left & center) |
                         (left & ~center & right) |
                         (left & center & ~right) |
                         (~left & ~center & right));
        end
    end

    // Sequential logic: update on positive edge of clock
    always_ff @(posedge clk) begin
        if (load)
            q_reg <= data;   // Load the provided data
        else
            q_reg <= next_q; // Advance the CA by one time step
    end

    // Output assignment
    assign q = q_reg;

endmodule

