module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    output walk_left,
    output walk_right
);

// Internal state encoding:
// 1'b0 : Walking Left
// 1'b1 : Walking Right

reg state;

// Next-state logic (Moore FSM)
// The Lemming switches direction if bumped on the side it is facing,
// or if bumped on both sides. It holds course if bumped on the opposite side.
assign next_state = (~state & bump_left) | (state & ~bump_right);

// Sequential logic: positive edge triggered clock, asynchronous active-high reset
always @(posedge clk or posedge areset) begin
    if (areset) begin
        // Asynchronous reset forces the Lemming to walk left
        state <= 1'b0;
    end else begin
        state <= next_state;
    end
end

// Output logic (Moore machine: outputs depend only on the current state)
assign walk_left = ~state;  // 1 when walking left
assign walk_right = state;  // 1 when walking right

endmodule

