module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic in,
    output logic out
);

// State encoding (2 bits)
typedef enum logic [1:0] {A = 2'b00, B = 2'b01, C = 2'b10, D = 2'b11} state_t;
state_t state, next_state;

// Next-state logic (combinational)
always @(*) begin
    case (state)
        A: next_state = state_t'(in ? B : A);
        B: next_state = state_t'(in ? B : C);
        C: next_state = state_t'(in ? D : A);
        D: next_state = state_t'(in ? B : C);
    endcase
end

// State flip-flops with positive-edge-triggered asynchronous reset
always @(posedge clk or posedge areset) begin
    if (areset)
        state <= A;
    else
        state <= next_state;
end

// Moore output: 1 only in state D
assign out = (state == D) ? 1'b1 : 1'b0;

endmodule

