module TopModule (
    input  logic clk,
    input  logic load,
    input  logic [511:0] data,
    output logic [511:0] q
);

    // Internal register to hold the current CA state
    logic [511:0] q_reg;

    // Next-state calculation register
    logic [511:0] q_next;

    // Combinational logic to calculate the next state according to Rule 90
    always_comb begin
        // Boundary conditions: q[-1] = 0 and q[512] = 0
        // Cell 0: Left neighbor is 0, Right neighbor is q_reg[1]
        q_next[0] = q_reg[1];              // 0 XOR q[1]
        // Cell 511: Left neighbor is q_reg[510], Right neighbor is 0
        q_next[511] = q_reg[510];          // q[510] XOR 0

        // Internal cells 1 through 510
        for (int i = 1; i <= 510; i = i + 1) begin
            q_next[i] = q_reg[i-1] ^ q_reg[i+1];
        end
    end

    // Sequential logic: positive edge triggered clock
    always_ff @(posedge clk) begin
        if (load) begin
            // Load the parallel data input into the register
            q_reg <= data;
        end else begin
            // Advance the cellular automaton by one time step
            q_reg <= q_next;
        end
    end

    // Assign the internal register to the output port
    assign q = q_reg;

endmodule

