module TopModule (
    input clk,
    input reset,
    input data,
    input done_counting,
    input ack,
    output shift_ena,
    output counting,
    output done
);

    parameter S_IDLE = 2'd0, S_SHIFT = 2'd1, S_COUNT = 2'd2, S_DONE = 2'd3;

    reg [1:0] state, next_state;
    reg [3:0] pat_shift;
    reg [1:0] shift_cnt;

    reg r_shift_ena, r_counting, r_done;

    assign shift_ena = r_shift_ena;
    assign counting = r_counting;
    assign done = r_done;

    always @(posedge clk) begin
        if (reset) begin
            state <= S_IDLE;
            pat_shift <= 4'd0;
            shift_cnt <= 2'd0;
            r_shift_ena <= 1'b0;
            r_counting <= 1'b0;
            r_done <= 1'b0;
        end else begin
            shift_cnt <= shift_cnt;
            r_shift_ena <= 1'b0;
            r_counting <= 1'b0;
            r_done <= 1'b0;

            case (state)
                S_IDLE: begin
                    pat_shift <= {pat_shift[2:0], data};
                    if (pat_shift == 4'b1101)
                        next_state <= S_SHIFT;
                    else
                        next_state <= S_IDLE;
                end

                S_SHIFT: begin
                    r_shift_ena <= 1'b1;
                    if (shift_cnt == 2'd3) begin
                        next_state <= S_COUNT;
                        shift_cnt <= 2'd0;
                    end else begin
                        next_state <= S_SHIFT;
                        shift_cnt <= shift_cnt + 2'd1;
                    end
                end

                S_COUNT: begin
                    r_counting <= 1'b1;
                    if (done_counting)
                        next_state <= S_DONE;
                    else
                        next_state <= S_COUNT;
                end

                S_DONE: begin
                    r_done <= 1'b1;
                    if (ack)
                        next_state <= S_IDLE;
                    else
                        next_state <= S_DONE;
                end

                default: next_state <= S_IDLE;
            endcase
        end
    end

endmodule

