Prob142_lemmings2.code:
module TopModule (
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    input ground,
    output walk_left,
    output walk_right,
    output aaah
);

    // State encoding
    parameter S_LEFT   = 2'b00;
    parameter S_RIGHT  = 2'b01;
    parameter S_FALL_L = 2'b10;
    parameter S_FALL_R = 2'b11;

    reg [1:0] state, next_state;

    // Sequential logic: async positive-edge reset to S_LEFT
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= S_LEFT;
        else
            state <= next_state;
    end

    // Combinational next-state logic
    always @(*) begin
        next_state = state;

        case (state)
            S_LEFT, S_RIGHT: begin
                if (ground == 0) begin
                    // Fall and remember current walking direction
                    if (state == S_LEFT)
                        next_state = S_FALL_L;
                    else
                        next_state = S_FALL_R;
                end else begin
                    // Ground present: process bumps
                    if (bump_left & bump_right) begin
                        // Bumped on both sides → switch directions
                        if (state == S_LEFT)
                            next_state = S_RIGHT;
                        else
                            next_state = S_LEFT;
                    end else if (bump_left)
                        next_state = S_RIGHT;
                    else if (bump_right)
                        next_state = S_LEFT;
                    // else: stay in current state
                end
            end

            S_FALL_L: begin
                if (ground == 1)
                    next_state = S_LEFT;   // resume walking left
                else
                    next_state = S_FALL_L; // still falling, ignore bumps
            end

            S_FALL_R: begin
                if (ground == 1)
                    next_state = S_RIGHT;  // resume walking right
                else
                    next_state = S_FALL_R; // still falling, ignore bumps
            end

            default: next_state = S_LEFT;
        endcase
    end

    // Moore output assignments
    assign walk_left = (state == S_LEFT);
    assign walk_right = (state == S_RIGHT);
    assign aaah       = (state == S_FALL_L) | (state == S_FALL_R);

endmodule

