module TopModule (
  input  clk,
  input  reset,
  input  in,
  output done
);
  reg done;
  reg [1:0] state;
  reg [1:0] next_state;
  parameter IDLE = 2'b00, DATA = 2'b01, STOP = 2'b10;
  reg [2:0] bit_cnt;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      done <= 0;
      bit_cnt <= 0;
    end else begin
      case (state)
        IDLE: begin
          done <= 0;
          if (in == 0)
            next_state <= DATA;
          else
            next_state <= IDLE;
          bit_cnt <= 0;
        end
        DATA: begin
          if (bit_cnt == 3'd7)
            next_state <= STOP;
          else
            next_state <= DATA;
          bit_cnt <= bit_cnt + 1;
        end
        STOP: begin
          if (in == 1) begin
            done <= 1;
            next_state <= IDLE;
          end else begin
            done <= 0;
            next_state <= IDLE;
          end
        end
      endcase
      state <= next_state;
    end
  end
endmodule
